import { Player, PlayerEvent, type ErrorEvent, type PlayerAPI } from "bitmovin-player";
import { UIFactory, type UIManager } from "bitmovin-player-ui";
import "bitmovin-player-ui/dist/css/bitmovinplayer-ui.css";

export function mountMinimalPlayer(licenseKey: string, hlsUrl: string) {
  const container = document.createElement("div");
  container.style.aspectRatio = "16 / 9";
  document.body.append(container);
  let player: PlayerAPI;
  try {
    player = new Player(container, {
      key: licenseKey,
      ui: false,
      playback: { autoplay: false, muted: true },
    });
  } catch (error) {
    container.remove();
    throw error;
  }
  let ui: UIManager | undefined;
  let released = false;
  let cleanup: Promise<void> | undefined;
  const onError = (event: ErrorEvent) => {
    if (!released) console.error(`Player error ${event.code}`);
  };
  player.on(PlayerEvent.Error, onError);

  function release(): Promise<void> {
    if (cleanup) return cleanup;
    released = true;
    window.removeEventListener("pagehide", onPageHide);
    player.off(PlayerEvent.Error, onError);
    cleanup = Promise.resolve().then(async () => {
      try {
        ui?.release();
      } finally {
        try {
          await player.destroy();
        } finally {
          container.remove();
        }
      }
    });
    return cleanup;
  }
  function onPageHide() {
    void release().catch(() => console.error("Player cleanup failed."));
  }
  window.addEventListener("pagehide", onPageHide, { once: true });

  const ready = Promise.resolve().then(async () => {
    if (released) return;
    ui = UIFactory.buildUI(player);
    await player.load({ hls: hlsUrl });
  }).catch(async (error: unknown) => {
    await release();
    throw error;
  });
  return { player, ready, release };
}

import { mountMinimalPlayer } from "./minimal-player";

try {
  const session = mountMinimalPlayer("YOUR_PLAYER_KEY", "https://example.com/video/master.m3u8");
  void session.ready.catch(() => console.error("Player setup failed."));
  // In an SPA, await session.release() when removing this view.
} catch {
  console.error("Player creation failed.");
}

const instance = new Player(playerEl as HTMLElement, config);
player = instance;
if (sdkUiEnabled) { renderThemeBar(); renderActiveConstruction(); apiExplorer?.refresh(); }
else applyTheme(instance, currentThemeId);
wireMetrics(instance);

async function loadCurrentSource(instance: PlayerAPI, forceTechnology?: string, disableSeeking?: boolean): Promise<void> {
  const generation = ++sourceLoadGeneration;
  const isLive = SOURCES.find((source) => source.id === currentSourceId)?.isLive ?? false;
  const settle = controlPanel?.beginSourceLoad(isLive);
  const base = deepMerge((apiSourceInput ?? sourcePreset) as SourceConfig, sourceOverrides);
  const source = apiExplorer?.prepare("SourceConfig", base) ?? structuredClone(base);
  currentSource = source;
  const request = { player: instance, source, settle };
  appSourceLoad = request;
  try {
    await instance.load(request.source, forceTechnology, disableSeeking);
  } catch (error) {
    if (appSourceLoad === request) appSourceLoad = undefined;
    if (player === instance && generation === sourceLoadGeneration) request.settle?.();
    throw error;
  } finally {
    if (player === instance && generation === sourceLoadGeneration) configPanel?.refresh();
  }
}

function dynAdapt(mutate: (cur: DynamicAdaptationConfig) => DynamicAdaptationConfig): void {
  const p = options.getPlayer();
  if (!p) return;
  p.adaptation.setConfig(mutate(p.adaptation.getConfig()));
}

