import type { PlayerAPI } from "bitmovin-player";
import {
  UIFactory, UIComponentLayoutOverride, type UIConfig,
} from "bitmovin-player-ui";
import "bitmovin-player-ui/dist/css/bitmovinplayer-ui.css";

export const uiConfig: UIConfig = {
  localization: { language: "en" },
  componentLayoutOverrides: {
    PlaybackSpeedSelectBox: UIComponentLayoutOverride.Exclude,
  },
  componentConfigOverrides: {
    UIContainer: { hideDelay: -1 },
  },
};

export function attachStandardUi(player: PlayerAPI) {
  return UIFactory.buildUI(player, uiConfig);
}

function applyTheme(p: PlayerAPI, id: ThemeId): void {
  if (sdkUiEnabled) return;
  const previousUi = uiManager;
  uiManager = undefined;
  apiExplorer?.refresh();
  previousUi?.release();
  const theme = THEMES.find((t) => t.id === id) ?? THEMES[0]!;
  const baseUi = themeConfig(theme.id);
  activeUiBase = baseUi;
  const appliedUi = apiExplorer?.prepare("UIConfig", baseUi) ?? baseUi;
  uiManager = theme.build(p, autohideEnabled ? undefined : -1, appliedUi, castingButtons);
  currentThemeId = theme.id;
  renderThemeBar();
  renderActiveConstruction();
  apiExplorer?.refresh();
  refreshUiControls();

import type { PlayerAPI } from "bitmovin-player";
import { DefaultUIFactory } from "@showcase/ui-shared";
import "@showcase/ui-shared/css";

export function createNeonUi(player: PlayerAPI) {
  return DefaultUIFactory.buildDefaultUI(player, undefined, {
    extraCssClasses: ["ui-skin-neon"],
    hideDelay: -1,
  });
}

.bmpui-ui-skin-neon .bmpui-seekbar-playbackposition {
  background: linear-gradient(90deg, #00e5ff, #ff2bd6);
  box-shadow: 0 0 8px rgba(0, 229, 255, 0.85);
}

import type { PlayerAPI } from "bitmovin-player";
import {
  BufferingOverlay, Container, ControlBar, PlaybackTimeLabel,
  PlaybackTimeLabelMode, PlaybackToggleButton, SeekBar, SeekBarLabel,
  UIContainer, UIManager, UIVariantIdentifier,
} from "bitmovin-player-ui";
import "@showcase/ui-shared/css";

export function createCompactUi(player: PlayerAPI) {
  const container = new UIContainer({
    components: [
      new BufferingOverlay(),
      new ControlBar({ components: [
        new Container({
          components: [
            new PlaybackToggleButton(),
            new SeekBar({ label: new SeekBarLabel() }),
            new PlaybackTimeLabel({
              timeLabelMode: PlaybackTimeLabelMode.CurrentTime,
            }),
          ],
          cssClasses: ["controlbar-bottom"],
        }),
      ] }),
    ],
    cssClasses: ["ui-skin-modern", "ui-skin-compact"],
    hideDelay: -1,
  });
  return new UIManager(player, [{
    ui: container,
    identifier: UIVariantIdentifier.main,
  }]);
}
